 "They wait an hour, text you, and remember it.": "Esperan una hora, te escriben y lo recuerdan.",
 "They wait an hour, write you an angry letter, and remember it.": "Esperan una hora, te escriben una carta enfadada y lo recuerdan.",
 "Applying is a roll: what you are good at and the traits the job looks for are your bonus (the chance is shown); with neither it is a long shot, and a job beyond your reach won't see you at all. After a no, try again the next day; each no in a row at the same place waits longer, until you get better at what it asks for or a new season comes. Shower first: nobody hires someone who smells.": "Postularse es una tirada: lo que haces bien y los rasgos que busca el puesto son tu bonificación (se muestra la probabilidad); sin ninguno de los dos, es una apuesta difícil, y un puesto fuera de tu alcance ni te recibe. Después de un no, inténtalo al día siguiente; cada no seguido en el mismo sitio espera más, hasta que mejores en lo que piden o llegue una nueva estación. Dúchate antes: nadie contrata a quien huele mal.",
 "Asking for work is a roll: what you are good at and the traits the trade looks for are your bonus (the chance is shown); with neither it is a long shot, and a trade beyond your reach won't see you at all. After a no, try again the next day; each no in a row at the same place waits longer, until you get better at what it asks for or a new season comes. Wash first: nobody takes on someone who smells.": "Pedir trabajo es una tirada: lo que haces bien y los rasgos que busca el oficio son tu bonificación (se muestra la probabilidad); sin ninguno de los dos, es una apuesta difícil, y un oficio fuera de tu alcance ni te recibe. Después de un no, inténtalo al día siguiente; cada no seguido en el mismo sitio espera más, hasta que mejores en lo que piden o llegue una nueva estación. Lávate antes: nadie acoge a quien huele mal.",
