 "Visitors: invite people over from the Calendar. They arrive about an hour later, ring the doorbell and stay until you say goodbye. You choose where each one sleeps.": "Visitas: invita a gente desde el Calendario. Llegan más o menos una hora después, tocan el timbre y se quedan hasta que te despides. Tú eliges dónde duerme cada una.",
 "Parties can have guests from outside, or happen somewhere out. Edit the guests on the party card, and ask someone to stay after the party.": "Las fiestas pueden tener invitados de fuera o celebrarse fuera de casa. Edita los invitados en la tarjeta de la fiesta y pide a alguien que se quede después.",
