 "Rain and storm sounds, with their own volume in Settings.": "Sonidos de lluvia y tormenta, con su propio volumen en Ajustes.",
 "Cards: sprites on the left or the right. Visual novel: the dialog box on the left, with the width you choose.": "Tarjetas: sprites a la izquierda o a la derecha. Novela visual: el cuadro de diálogo a la izquierda, con el ancho que elijas.",
 "This Home comes first in the menu and holds the Home settings. More kinds of family ties.": "Este Home aparece primero en el menú y guarda los ajustes de Home. Más tipos de lazos familiares.",
 "Safety: world files and slash commands can no longer run code (thanks, coldasblues). A spouse added later now shows as Married.": "Seguridad: los archivos de mundo y los slash commands ya no pueden ejecutar código (gracias, coldasblues). Un cónyuge añadido después ahora aparece como casado.",
 "Visitors": "Visitas",
 "Home: a new way to play. One house, the characters you choose, and no work, money or bills: just the people and the story.": "Home: una nueva forma de jugar. Una casa, los personajes que elijas, y nada de trabajo, dinero ni facturas: solo la gente y la historia.",
 "A ready Home, The Shared House, or your own one made in the Home creator.": "Un Home listo, The Shared House, o uno tuyo hecho en el creador de Home.",
 "Houses with floors and a floor plan, Go out to take the story anywhere, Who lives here to move people in and out, and a dress code for each room.": "Casas con pisos y plano, Salir para llevar la historia a cualquier lugar, Quién vive aquí para que la gente se mude, y un código de vestimenta para cada habitación.",
 "In a Home, the clock moves a little with each message. Click it to let time pass.": "En un Home, el reloj avanza un poco con cada mensaje. Haz clic en él para dejar pasar el tiempo.",
