 "Image Generation": "Generación de imágenes",
 "Draws pictures with SillyTavern's Image Generation. A picture button next to Send opens its options (the character, their face, you, the whole story, the last message, a background); the picture appears in the chat.": "Dibuja imágenes con la Generación de imágenes de SillyTavern. Un botón de imagen junto a Enviar abre sus opciones (el personaje, su cara, tú, toda la historia, el último mensaje, un fondo); la imagen aparece en el chat.",
 "Installed, but no image source is chosen: pick one in SillyTavern's Extensions → Image Generation.": "Instalada, pero no hay fuente de imágenes elegida: elige una en Extensiones → Generación de imágenes de SillyTavern.",
 "This extension has no settings of its own in the Extensions tab.": "Esta extensión no tiene ajustes propios en la pestaña Extensiones.",
 "· built into SillyTavern": "· incluida en SillyTavern",
 "Silence notices about characters without a voice{2}": "Silenciar avisos de personajes sin voz{2}",
 "TTS warns about each character with no voice, a disabled voice or one missing from the voice map. On: those notices are not shown.": "El TTS avisa de cada personaje sin voz, con la voz desactivada o fuera del mapa de voces. Activado: esos avisos no se muestran.",
 "(not recommended to turn off)": "(no se recomienda desactivar)",
