 "What Mundi sends to the AI": "Lo que Mundi envía a la IA",
 "Sent with every reply, on top of your preset, the character cards and the chat. Only what is about this place and the people here.": "Se envía con cada respuesta, además de tu preset, las tarjetas de personajes y el chat. Solo lo que trata de este lugar y la gente de aquí.",
 "Token budget for Mundi · {4}": "Presupuesto de tokens de Mundi · {4}",
 "Over the budget, Mundi leaves out the least important blocks first (rumors, then approval…). The scene basics are always sent.": "Por encima del presupuesto, Mundi deja fuera primero los bloques menos importantes (rumores, luego aprobación…). Lo básico de la escena siempre se envía.",
 "Blocks": "Bloques",
 "Rules of the scene": "Reglas de la escena",
 "Sent last, after everything else. Empty: Mundi's own rules (shown greyed). The note about the language of replies is added by itself.": "Se envía al final, después de todo. Vacío: las reglas propias de Mundi (en gris). La nota sobre el idioma de las respuestas se añade sola.",
 "SillyTavern's context size is unlocked ({0}): set it to your model's real context in AI Response Configuration.": "El tamaño de contexto de SillyTavern está desbloqueado ({0}): ajústalo al contexto real de tu modelo en AI Response Configuration.",
