 "), or leave it out to send only your words. Your text is sent only when the block has something to say. Empty: Mundi's own text.": "), o déjalo fuera para enviar solo tus palabras. Tu texto solo se envía cuando el bloque tiene algo que decir. Vacío: el texto propio de Mundi.",
