 "Saved as SillyTavern themes named \"Mundi - …\". They change the chat's look and tint the HUD's glass (panels, menus, cards).": "Se guardan como temas de SillyTavern llamados \"Mundi - …\". Cambian el aspecto del chat y tiñen el cristal del HUD (paneles, menús, tarjetas).",
