 "{0} Taking": "{0} Cursando",
 ": day {2} of {3}. Study once a day, {4}.": ": día {2} de {3}. Estudia una vez al día, {4}.",
 "Drop it": "Dejarlo",
 "Pay once, then study a little each day (2 h, {0}). Each day counts once. When you finish, you learn its traits for good: they help in every roll, and some jobs ask for a course.": "Paga una vez y luego estudia un poco cada día (2 h, {0}). Cada día cuenta una vez. Al terminar, aprendes sus rasgos para siempre: ayudan en cada tirada, y algunos empleos piden un curso.",
 "{4} · {5} day{6} · {7}": "{4} · {5} día{6} · {7}",
 "✓ Finished": "✓ Terminado",
 "In progress · {0}/{1}": "En curso · {0}/{1}",
 "Enroll · {3}": "Inscribirse · {3}",
 "Skills": "Habilidades",
 "Earned with life goals": "Obtenidos con metas de vida",
 "Education": "Educación",
 "{9} Experience": "{9} Experiencia",
 "{11} Skills and traits": "{11} Habilidades y rasgos",
 "Each trait that fits what you do is +2 on its roll (interviews, cooking, workouts…).": "Cada rasgo que encaja con lo que haces es +2 en su tirada (entrevistas, cocina, entrenamientos…).",
 "{20} Life goals reached": "{20} Metas de vida alcanzadas",
 "{23} Activity": "{23} Actividad",
 "Fitness {24}/100 · {25} meals cooked · {26} good workouts · {27} parties": "Forma física {24}/100 · {25} comidas cocinadas · {26} buenos entrenamientos · {27} fiestas",
 "{1} · rank {2} of {3}": "{1} · rango {2} de {3}",
 "No traits yet.": "Aún no hay rasgos.",
 "In progress · day {2} of {3}{4}": "En curso · día {2} de {3}{4}",
 "· studied today": "· estudiado hoy",
 "✓ Finished · {2}": "✓ Terminado · {2}",
 "Enrolled: {0}. Study once a day, {1}.": "Inscrito: {0}. Estudia una vez al día, {1}.",
 "You dropped the course. What you studied is kept if you take it again.": "Dejaste el curso. Lo que estudiaste se guarda si lo vuelves a hacer.",
 "Words (lexicon)": "Palabras (léxico)",
 "Character creation": "Creación de personaje",
 "Customs & calendar": "Costumbres y calendario",
 "Realm & factions": "Reino y facciones",
 "Economy & skies": "Economía y cielos",
 "People & routines": "Gente y rutinas",
 "About this {0}": "Sobre este {0}",
 "Up to {5} characters. Only you see it: it is not sent to the AI (the setting below is).": "Hasta {5} caracteres. Solo lo ves tú: no se envía a la IA (el escenario de abajo sí).",
 "The picture on the {13}'s card. Best at 16:9 (1400 × 782).": "La imagen de la tarjeta del {13}. Mejor en 16:9 (1400 × 782).",
 "Look: style and skin": "Aspecto: estilo y skin",
 "Mix them as you like: the rules and the people stay the same. Players can still pick another skin in their settings.": "Combínalos como quieras: las reglas y la gente siguen igual. Los jugadores aún pueden elegir otra skin en sus ajustes.",
 "Travel: 30 minutes inside a town, 2 hours between towns.": "Viaje: 30 minutos dentro de una ciudad, 2 horas entre ciudades.",
 "Each part of the day can change what is open (Maps: a place's \"Closed at\"), what things cost out and about (Prices ×, empty = as listed) and how places, homes and maps look (a picture for each part of the day).": "Cada parte del día puede cambiar qué está abierto (Mapas: el \"Cerrado a las\" de un lugar), cuánto cuestan las cosas fuera (Precios ×, vacío = como se indica) y cómo se ven lugares, casas y mapas (una imagen para cada parte del día).",
 "Made for (the tag on its card)": "Hecho para (la etiqueta de su tarjeta)",
 "Show every tab": "Mostrar todas las pestañas",
 "A Home hides Realm, Economy and RPG (a Home is always Life-Sim). Jobs and courses happen off-screen.": "Un Home oculta Reino, Economía y RPG (un Home siempre es Life-Sim). Los empleos y cursos ocurren fuera de escena.",
 "Premise (how the story starts: shown when the game begins, and told to the AI)": "Premisa (cómo empieza la historia: se muestra al empezar la partida y se le cuenta a la IA)",
 "Or use a room's picture": "O usa la imagen de una habitación",
 "Style (the words of the game and the device)": "Estilo (las palabras del juego y el aparato)",
 "Skin (colors of the HUD)": "Skin (colores del HUD)",
 "The symbol goes after the amount (\"40 g\")": "El símbolo va detrás de la cantidad (\"40 g\")",
 "×1 (1 real second = 1 game minute)": "×1 (1 segundo real = 1 minuto de juego)",
 "Prices ×": "Precios ×",
 "What kind of world": "Qué tipo de mundo",
 "How things work here": "Cómo funcionan las cosas aquí",
 "A system turned off is gone from the HUD, the {10} and what the AI is told, and the game stops running it. Saves keep its data: turn it back on and it picks up where it was.": "Un sistema desactivado desaparece del HUD, del {10} y de lo que se le dice a la IA, y el juego deja de ejecutarlo. Las partidas guardan sus datos: actívalo de nuevo y sigue donde estaba.",
 "Realistic or fantasy: what it holds (magic, gods, familiars and weapons with a soul only in fantasy). {0}": "Realista o fantasía: lo que contiene (magia, dioses, familiares y armas con alma solo en fantasía). {0}",
 "Life-Sim and RPG: the ways it can be played (with both, the player chooses when starting). Realistic or fantasy: what it holds (magic, gods, familiars and weapons with a soul only in fantasy).": "Life-Sim y RPG: las formas de jugarlo (con las dos, el jugador elige al empezar). Realista o fantasía: lo que contiene (magia, dioses, familiares y armas con alma solo en fantasía).",
 "Game mode": "Modo de juego",
 "How a new game starts (the player can pick another way the tags allow).": "Cómo empieza una partida nueva (el jugador puede elegir otra forma que permitan las etiquetas).",
 "Custom: turn each need on or off in the Needs tab, and the systems below here.": "Personalizado: activa o desactiva cada necesidad en la pestaña Necesidades, y los sistemas de aquí abajo.",
 "On": "Activado",
 "title=\"Its system is off (Systems, below)\"": "title=\"Su sistema está desactivado (Sistemas, abajo)\"",
 "The device looks like": "El aparato es",
 "A phone (apps on a screen)": "Un móvil (apps en una pantalla)",
 "A journal (an open book with pages)": "Un diario (un libro abierto con páginas)",
 "The social app is": "La app social es",
 "A social network (posts, likes and replies)": "Una red social (publicaciones, me gusta y respuestas)",
 "A notice board (notices; whoever answers writes you a letter)": "Un tablón (anuncios; quien responde te escribe una carta)",
 "Messages are": "Los mensajes son",
 "Text messages": "Mensajes de texto",
 "Letters carried by a courier": "Cartas llevadas por un mensajero",
 "How people write (what the AI is told for messages and posts)": "Cómo escribe la gente (lo que se le dice a la IA para mensajes y publicaciones)",
 "Needs {0} on.": "Necesita {0} activado.",
 "Made for {0} worlds: off unless you turn it on.": "Hecho para mundos {0}: desactivado salvo que lo actives.",
 "Off: homes are free (the other bills stay).": "Desactivado: las casas son gratis (las demás facturas siguen).",
 "Only in the RPG mode": "Solo en el modo RPG",
 "Like health: out of Life-Sim worlds.": "Como la salud: fuera de los mundos Life-Sim.",
 "Turned off in this world": "Desactivado en este mundo",
 "You pass out… The bill is {cost}.": "Te desmayas… La factura es {cost}.",
 "A crisis after a while at zero": "Una crisis tras un rato a cero",
 "Once each time it hits zero: you faint, you break down… People who see it remember it.": "Una vez cada vez que llega a cero: te desmayas, te derrumbas… Quien lo ve lo recuerda.",
 "After … minutes at zero": "Tras … minutos a cero",
 "You end up at": "Acabas en",
