 "You feel faint and nearly collapse…": "Te sientes débil y casi te desplomas…",
 "Your mood changes by": "Tu ánimo cambia en",
 "People who saw it think less of you by": "Quien lo vio piensa peor de ti en",
 "What the people who saw it remember ({u} = you, {0} = the place)": "Lo que recuerda quien lo vio ({u} = tú, {0} = el lugar)",
 "{u} nearly fainted at {0}.": "{u} casi se desmaya en {0}.",
 "Have a coffee": "Tomar un café",
 "But not in places tagged": "Pero no en lugares con la etiqueta",
 "An outing (off-screen)": "Una salida (fuera de escena)",
 "You leave for a while (work, errands, a night out) and come back: offered even when needs are off. Made for Homes.": "Sales un rato (trabajo, recados, una noche fuera) y vuelves: se ofrece aunque las necesidades estén desactivadas. Hecho para Homes.",
