 "Goods": "Mercancías",
 "Bought and sold at markets (places tagged shop). Cheap where they are made, dear where they are scarce; illegal ones can be found by guards. A good with id camping_gear lets you rest at camp in a storm.": "Se compran y venden en mercados (lugares con la etiqueta shop). Baratas donde se fabrican, caras donde escasean; los guardias pueden encontrar las ilegales. Una mercancía con id camping_gear te deja descansar en el campamento durante una tormenta.",
 "Crafting": "Fabricación",
 "Recipes turn goods into goods at the right place (an id, a tag, part of a name, or home). Legendary ones make a named artifact.": "Las recetas convierten mercancías en otras en el lugar adecuado (un id, una etiqueta, parte de un nombre, o casa). Las legendarias crean un artefacto con nombre.",
 "Found deep in towers or won at auctions (a good of the kind \"a weapon with a will\").": "Se encuentra en lo profundo de las torres o se gana en subastas (una mercancía del tipo \"un arma con voluntad\").",
