 "Secret (only shown once you have dealings with it)": "Secreta (solo se muestra cuando tratas con ella)",
 "Habits that become traits": "Hábitos que se vuelven rasgos",
 "Do something often enough in a few days and it becomes a trait (jobs like it, the AI knows it); stop for long and it fades.": "Haz algo bastantes veces en pocos días y se vuelve un rasgo (a los empleos les gusta, la IA lo sabe); déjalo mucho tiempo y se desvanece.",
 "Shows, matches, fairs: on a weekday, every few weeks, at a place. They are in the calendar and you go if you want.": "Espectáculos, partidos, ferias: un día de la semana, cada pocas semanas, en un lugar. Están en el calendario y vas si quieres.",
 "Practice levels them up (to 10): +1 on their rolls every 2 levels, more money each level, and jobs can ask for a level.": "Practicar los sube de nivel (hasta 10): +1 en sus tiradas cada 2 niveles, más dinero cada nivel, y los empleos pueden pedir un nivel.",
 "A ladder of ranks (students first, the head last), tuition, lessons, exams and clubs. Its staff (the people who work at the place) are its faculty.": "Una escalera de rangos (alumnos primero, el director al final), matrícula, clases, exámenes y clubes. Su personal (quien trabaja en el lugar) es el profesorado.",
