 "The RPG mode needs the world's RPG: attributes, skills, classes (with a subclass at level 3 or 5), magic and titles. Start from the medieval one and change what you like, or from nothing.": "El modo RPG necesita el RPG del mundo: atributos, habilidades, clases (con una subclase en el nivel 3 o 5), magia y títulos. Empieza por el medieval y cambia lo que quieras, o desde cero.",
