 "Daily wage per level": "Paga diaria por nivel",
 "Career paths": "Caminos de carrera",
 "At some ranks (3, 6, 9 in the built-in careers) the player chooses a path; its ranks come next.{0}": "En algunos rangos (3, 6, 9 en las carreras incluidas) el jugador elige un camino; sus rangos vienen después.{0}",
 "Add a choice of paths": "Añadir una elección de caminos",
 "Ranks after rank {0} above are not used: the paths replace them.": "Los rangos después del rango {0} de arriba no se usan: los caminos los sustituyen.",
 "Remove these paths": "Quitar estos caminos",
 "Add a path": "Añadir un camino",
 "Choose at rank": "Elegir en el rango",
 "Traits that help on this path": "Rasgos que ayudan en este camino",
 "Remove this path": "Quitar este camino",
 "Path": "Camino",
 "Shifts to reach it": "Turnos para llegar",
 "Only after (empty: after any)": "Solo después de (vacío: después de cualquiera)",
 "Players pay once, then study a little each day (at home or where a place is tagged \"study\"). When they finish, they learn the course's traits for good.": "Los jugadores pagan una vez y luego estudian un poco cada día (en casa o donde un lugar tenga la etiqueta \"study\"). Al terminar, aprenden los rasgos del curso para siempre.",
 "{2} days · {3}": "{2} días · {3}",
 "aria-disabled=\"true\" title=\"Give the course a trait to teach first\"": "aria-disabled=\"true\" title=\"Primero dale al curso un rasgo que enseñar\"",
 "Required for these jobs": "Obligatorio para estos empleos",
 "Helps in these jobs (faster promotions)": "Ayuda en estos empleos (ascensos más rápidos)",
 "Improves these skills (+2 on their roll)": "Mejora estas habilidades (+2 en su tirada)",
 "Area": "Área",
 "Days of study": "Días de estudio",
 "Price ({0})": "Precio ({0})",
 "Teaches these traits": "Enseña estos rasgos",
 "Separated by commas. A trait can be new; it helps wherever it is asked for.": "Separados por comas. Un rasgo puede ser nuevo; ayuda donde se pida.",
 "Traits of this world: {0}": "Rasgos de este mundo: {0}",
 "No jobs yet.": "Aún no hay empleos.",
 "No things to do with a roll yet (Things to do → a roll).": "Aún no hay cosas que hacer con tirada (Cosas que hacer → una tirada).",
 "No courses yet.": "Aún no hay cursos.",
 "Mood when you wake up at home (+)": "Ánimo al despertar en casa (+)",
 "Trips take this share of the time (0.5 = half; empty = not a vehicle)": "Los viajes tardan esta parte del tiempo (0.5 = la mitad; vacío = no es un vehículo)",
 "Unlocks: {0}.": "Desbloquea: {0}.",
 "Unlocks nothing to do yet: in Things to do, pick this item under \"Only if the player owns\".": "Aún no desbloquea nada: en Cosas que hacer, elige este objeto en \"Solo si el jugador tiene\".",
 "Nothing for sale.": "Nada a la venta.",
 "phone, rent, course…": "móvil, alquiler, curso…",
 "Words of the game": "Palabras del juego",
 "Every term the game shows or tells the AI, as the {0} style says it. Write your world's own word to replace it (a phone can be a \"Den Den Mushi\", a course \"training\"…); leave it empty to keep the style's. {0}, {1}… are filled in by the game (a name, a price…). Apps, places, jobs and needs are named in their own tabs.": "Cada término que el juego muestra o le dice a la IA, como lo dice el estilo {0}. Escribe la palabra de tu mundo para reemplazarlo (un móvil puede ser un \"Den Den Mushi\", un curso un \"entrenamiento\"…); déjalo vacío para mantener el del estilo. {0}, {1}… los rellena el juego (un nombre, un precio…). Las apps, lugares, empleos y necesidades se nombran en sus propias pestañas.",
 "{2} term{3} changed in this world.": "{2} término{3} cambiado{3} en este mundo.",
 "Nothing matches.": "Nada coincide.",
 "Expenses (besides the rent)": "Gastos (además del alquiler)",
 "Bills every home pays each week with the rent: water, power, firewood, servants, taxes… as many as you like, or none. Each kind of home sets its own amount above. One left unpaid for a week stops the things you pick here.": "Facturas que cada casa paga a la semana con el alquiler: agua, luz, leña, criados, impuestos… las que quieras, o ninguna. Cada tipo de casa fija su propia cantidad arriba. Una sin pagar durante una semana detiene las cosas que elijas aquí.",
 "Things that break at home": "Cosas que se rompen en casa",
 "Now and then one of these breaks and stops some things until it is fixed (by the player, or paying someone).": "De vez en cuando una de estas se rompe y detiene algunas cosas hasta que se arregla (el jugador, o pagando a alguien).",
 "{1} homes · {2}": "{1} casas · {2}",
 "{5} homes placed. They are numbered (House 1, House 2…).": "{5} casas colocadas. Están numeradas (Casa 1, Casa 2…).",
 "Inside at other times of the day": "Por dentro en otros momentos del día",
 "{0} a week ({1})": "{0} a la semana ({1})",
 "Use the usual one": "Usar la de siempre",
 "stops {0} thing{1}": "detiene {0} cosa{1}",
 "stops nothing": "no detiene nada",
 "When it is a week unpaid, it stops": "Con una semana sin pagar, detiene",
 "Like the upkeep of arms and gear: not billed in Life-Sim.": "Como el mantenimiento de armas y equipo: no se cobra en Life-Sim.",
 "Name (empty: the Words tab's word)": "Nombre (vacío: la palabra de la pestaña Palabras)",
 "Message when it stops (optional; {app} = where to pay)": "Mensaje al detenerse (opcional; {app} = dónde pagar)",
 "{0} was not paid for a week: it stopped until you pay it.": "{0} lleva una semana sin pagarse: se detuvo hasta que lo pagues.",
 "Message when it is paid again (optional)": "Mensaje al volver a pagarse (opcional)",
 "No expenses: homes only pay the rent.": "Sin gastos: las casas solo pagan el alquiler.",
 "Paying someone to fix it costs ({0})": "Pagar a alguien para arreglarlo cuesta ({0})",
 "stops {1}": "detiene {1}",
 "While broken, it stops": "Mientras está roto, detiene",
 "Name (as in \"Oh no: … broke at home\")": "Nombre (como en \"Oh, no: … se rompió en casa\")",
 "Nothing breaks.": "Nada se rompe.",
 "What the player chooses": "Lo que elige el jugador",
 "The parts of making a character this world asks for (a new character or a persona). Turned off, it is not asked: the first origin is used, and no traits or words about you.": "Las partes de crear un personaje que pide este mundo (un personaje nuevo o una persona). Desactivado, no se pregunta: se usa el primer origen, y ningún rasgo ni palabras sobre ti.",
 "A picture": "Una imagen",
 "New characters only.": "Solo personajes nuevos.",
