 "In the RPG": "En el RPG",
 "Trained skills": "Habilidades entrenadas",
 "What it gives you": "Qué te da",
 "Folk hero: common folk take you in.": "Héroe del pueblo: la gente sencilla te acoge.",
 "People of this world": "Gente de este mundo",
 "Each becomes a character card when a game of this world starts. Their job, home and routine say where they are each hour.": "Cada una se convierte en una tarjeta de personaje cuando empieza una partida de este mundo. Su empleo, casa y rutina dicen dónde está a cada hora.",
 "Shuffle everyone's job, home and routine": "Barajar el empleo, la casa y la rutina de todos",
 "Goes out to (free time)": "Sale a (tiempo libre)",
 "Relations": "Relaciones",
 "How {9} relates to the world's other people (any of them, wherever they live), from the start of every game.": "Cómo se relaciona {9} con la otra gente del mundo (cualquiera, viva donde viva), desde el inicio de cada partida.",
