 "their usual clothes": "su ropa de siempre",
 "Dress code": "Código de vestimenta",
 "What people wear in each room: the name of an outfit folder in their Expressions (a \"swimsuit\" folder for the pool, \"pajamas\" for the bedrooms…). Anyone who has it puts it on while in that room with you, and the AI is told; anyone who doesn't keeps their clothes. Empty: their usual clothes.": "Lo que lleva la gente en cada habitación: el nombre de una carpeta de ropa en sus Expressions (una carpeta \"swimsuit\" para la piscina, \"pajamas\" para los dormitorios…). Quien la tenga se la pone mientras esté en esa habitación contigo, y se le dice a la IA; quien no, sigue con su ropa. Vacío: su ropa de siempre.",
