 "the bank": "el banco",
 "a shady moneylender": "un prestamista sospechoso",
 "Time passes with each message": "El tiempo pasa con cada mensaje",
 "Each message you send is {1} minutes. Off: time only moves with \"Let time pass\", sleeping and what you do.": "Cada mensaje que envías son {1} minutos. Desactivado: el tiempo solo avanza con \"Dejar pasar el tiempo\", durmiendo y con lo que haces.",
 "The housemates leave the house": "Los compañeros salen de casa",
 "For work, errands and nights out (off-screen), then they come back. Off: everyone stays in.": "Para trabajar, hacer recados y salir de noche (fuera de escena), y luego vuelven. Desactivado: todos se quedan en casa.",
 "The job is what the AI is told they do. With a shift they are out of the house during it (when the housemates leave the house).": "El empleo es lo que se le dice a la IA que hace. Con un turno, está fuera de casa durante él (cuando los compañeros salen de casa).",
 "Job (optional): nurse, barista…": "Empleo (opcional): enfermera, barista…",
