 "Year {0}": "Año {0}",
 "Nothing happened this day.": "No pasó nada este día.",
 "Today's entry is written when you go to sleep.": "La entrada de hoy se escribe cuando te vas a dormir.",
 "No diary entry for this day.": "No hay entrada de diario para este día.",
