 "← Menu": "← Menú",
 "Pick a character card and go straight into a chat with them, in Mundi's scene. No map, no clock: just the story.": "Elige una tarjeta de personaje y entra directo a un chat con él, en la escena de Mundi. Sin mapa, sin reloj: solo la historia.",
