 "Floor plan": "Plano",
 "Optional. With a floor plan, the house map in the game is a plan of the house: one per floor, each room where it really is. Without one, the game shows the pictures of the rooms (as now).": "Opcional. Con un plano, el mapa de la casa en el juego es un plano de la casa: uno por piso, cada habitación donde realmente está. Sin él, el juego muestra las imágenes de las habitaciones (como ahora).",
