 "On the plan": "En el plano",
 "Rooms light up with": "Las habitaciones se iluminan con",
 "The boxes you draw here are the rooms: in the game, a room lights up when the mouse is over it, and a click goes there.": "Las cajas que dibujas aquí son las habitaciones: en el juego, una habitación se ilumina al pasar el ratón por encima, y un clic te lleva allí.",
 "Rooms {20}": "Habitaciones {20}",
 "Use the floors in the game": "Usar los pisos en el juego",
