 "Chat lorebooks": "Lorebooks del chat",
 "Lorebooks only for this chat; pick as many as you want. The first is SillyTavern's \"chat lore\"; the others are switched on while this chat is open. The character's own lorebooks keep working as usual.": "Lorebooks solo para este chat; elige los que quieras. El primero es el \"chat lore\" de SillyTavern; los demás se activan mientras este chat está abierto. Los lorebooks propios del personaje siguen funcionando.",
