 "Secondary color": "Color secundario",
 "Font": "Fuente",
 "Each message with a big rounded picture of who speaks beside it.": "Cada mensaje con una imagen grande y redondeada de quien habla al lado.",
 "Also in the scenario's side menu (Look) and the game menu. Saved in Mundi's own settings, apart from SillyTavern's.": "También en el menú lateral del escenario (Aspecto) y en el menú del juego. Se guarda en los ajustes propios de Mundi, aparte de los de SillyTavern.",
