 "Installed, but turned off: enable it in SillyTavern's Extensions → TTS.": "Instalada, pero desactivada: actívala en Extensiones → TTS de SillyTavern.",
 "Speech Recognition": "Reconocimiento de voz",
 "Talk instead of typing: a microphone button next to Send. What you say goes into the message box (or is sent, if the extension is set to send by itself).": "Habla en vez de escribir: un botón de micrófono junto a Enviar. Lo que dices va al cuadro de mensaje (o se envía, si la extensión está configurada para enviarlo sola).",
 "Installed, but no speech provider is chosen: pick one in SillyTavern's Extensions → Speech Recognition.": "Instalada, pero no hay proveedor de voz elegido: elige uno en Extensiones → Reconocimiento de voz de SillyTavern.",
 "Add-ons": "Complementos",
 "SillyTavern extensions that Mundi supports. Mundi checks by itself whether each one is installed; when it is, its button appears in the scene.": "Extensiones de SillyTavern que Mundi admite. Mundi comprueba solo si cada una está instalada; cuando lo está, su botón aparece en la escena.",
