 "Relationships": "Relaciones",
 "Romance": "Romance",
 "How fast feelings grow. The first points with someone come at full speed; after that each gain counts a little less, and the pace comes back over the next hours. Nothing ever stops completely.": "Lo rápido que crecen los sentimientos. Los primeros puntos con alguien llegan a toda velocidad; después cada ganancia cuenta un poco menos, y el ritmo vuelve en las horas siguientes. Nada se detiene del todo.",
