 "The pace comes back by half in": "El ritmo vuelve a la mitad en",
 "{0} h": "{0} h",
 "Show the numbers (debug)": "Mostrar los números (depuración)",
 "The raw values, how fast each relationship grows right now, and what each message changed, with undo. For tuning: the AI never sees it.": "Los valores exactos, lo rápido que crece cada relación ahora y lo que cambió cada mensaje, con deshacer. Para ajustar: la IA nunca lo ve.",
 "Turn on \"Advanced\" for how fast feelings grow and the debug view.": "Activa \"Avanzado\" para lo rápido que crecen los sentimientos y la vista de depuración.",
