 "people's feelings for each other never change, and couples between them never form, move on or end by themselves.": "lo que las personas sienten unas por otras nunca cambia, y las parejas entre ellas nunca se forman, avanzan ni terminan por sí solas.",
 "Who is whose sister or parent, who lives or works together, and how the people here feel about each other.": "Quién es hermana o padre de quién, quién vive o trabaja junto, y lo que las personas de aquí sienten unas por otras.",
 "Who is dating whom among the people here, and who used to.": "Quién sale con quién entre las personas de aquí, y quién salía antes.",
