 "Non-binary": "No binario",
 "New gender": "Nuevo género",
 "Genders": "Géneros",
 "Everyone can have one of these (or none). Who people are attracted to is set per gender.": "Cada persona puede tener uno de estos (o ninguno). Quién atrae a cada uno se define por género.",
 "Plural (for the AI)": "Plural (para la IA)",
 "Pronouns": "Pronombres",
 "No genders: nobody has one, and attraction does nothing.": "Sin géneros: nadie tiene uno y la atracción no hace nada.",
 "Add a gender": "Añadir un género",
 "Their ways": "Su manera de ser",
 "Where every game of this world starts from (a card's own Mundi settings come first). Unset: the defaults.": "Desde donde empieza cada partida de este mundo (los ajustes Mundi de la propia tarjeta van primero). Sin definir: lo predeterminado.",
 "Who they are": "Quiénes son",
 "Each one's gender and, under \"More\", who they are attracted to, how fast their feelings grow and how they are about intimacy. Taken from their card when it has Mundi settings; the cards are not changed.": "El género de cada uno y, en \"Más\", quién le atrae, lo rápido que crecen sus sentimientos y cómo vive la intimidad. Se toma de su tarjeta cuando tiene ajustes Mundi; las tarjetas no se cambian.",
 "More": "Más",
 "Less": "Menos",
 "Gender and attraction": "Género y atracción",
 "The gender and pronouns of the people here (and yours), and who they are attracted to when it is not everyone.": "El género y los pronombres de las personas aquí (y los tuyos), y quién les atrae cuando no es cualquiera.",
 "Attracted to": "Le atrae",
 "Everyone (default)": "Todo el mundo (predeterminado)",
 "Only: {0}": "Solo: {0}",
 "No one": "Nadie",
 "How fast feelings grow toward each gender (100% is normal, 0% never). Losses are never changed.": "Lo rápido que crecen los sentimientos hacia cada género (100% es lo normal, 0% nunca). Las pérdidas nunca cambian.",
 "Yours only sorts the dating app: while you play someone, their own feelings wait. It counts again once you stop playing them.": "La tuya solo ordena la app de citas: mientras juegas como alguien, sus propios sentimientos esperan. Vuelve a contar cuando dejas de jugar como esa persona.",
 "Turn on \"Advanced\" for who you are attracted to.": "Activa \"Avanzado\" para elegir quién te atrae.",
 "Suggest from the cards": "Sugerir desde las tarjetas",
 "{0} without a gender. Your AI reads each card once (gender, attraction, intimacy); nothing changes until you apply it.": "{0} sin género. Tu IA lee cada tarjeta una vez (género, atracción, intimidad); nada cambia hasta que lo apliques.",
 "Everyone has a gender.": "Todos tienen un género.",
 "Reading {0}'s card ({1}/{2})…": "Leyendo la tarjeta de {0} ({1}/{2})…",
 "The card does not say.": "La tarjeta no lo dice.",
 "attracted to: {0}": "le atrae: {0}",
 "attracted to no one": "no le atrae nadie",
 "only with a partner": "solo con pareja",
 "Apply all": "Aplicar todo",
 "Save to card": "Guardar en la tarjeta",
 "Their gender, attraction, pace and styles go to their card's Mundi settings, so new games with them start from these. Nothing else on the card changes.": "Su género, atracción, ritmo y estilos van a los ajustes Mundi de su tarjeta, y las nuevas partidas con esa persona empiezan desde ahí. Nada más cambia en la tarjeta.",
 "Saved to {0}'s card.": "Guardado en la tarjeta de {0}.",
 "Could not save the character.": "No se pudo guardar el personaje.",
 "Nothing changes until you apply what your AI read.": "Nada cambia hasta que apliques lo que leyó tu IA.",
 "Their initiatives": "Sus iniciativas",
 "Characters take the initiative": "Los personajes toman la iniciativa",
 "Rarely": "Rara vez",
 "Normal (default)": "Normal (predeterminado)",
 "Often": "A menudo",
 "People open up, confess, ask you out, text you, warn you before they leave and hold grudges on their own. Normal: at most one thing they start on their own a day, and every few days per person. Off: none of it.": "La gente se abre, se declara, te invita a salir, te escribe, te avisa antes de dejarte y guarda rencor por su cuenta. Normal: como mucho una cosa al día que empiezan solos, y cada pocos días por persona. Apagado: nada de eso.",
 "Asks you to come over tonight": "Te invita a su casa esta noche",
 "Not yet": "Todavía no",
 "Not tonight, but soon?": "Esta noche no, pero ¿pronto?",
 "You said no to {0}.": "Le dijiste que no a {0}.",
 "They are still upset with you.": "Todavía está molesto(a) contigo.",
 "What the people here bring up on their own this scene (opening up, a confession, asking you something), and what each one wants from you.": "Lo que las personas aquí sacan por su cuenta en esta escena (abrirse, una confesión, pedirte algo), y lo que cada una quiere de ti.",
 "Needs some time": "Necesita tiempo",
 "Their feelings have grown a lot lately: more will come, slowly, after some time.": "Sus sentimientos han crecido mucho últimamente: vendrá más, despacio, después de un tiempo.",
 "You have grown close quickly lately: more will come, slowly, after some time.": "Se han acercado rápido últimamente: vendrá más, despacio, después de un tiempo.",
 "Opinions spread through friends": "Las opiniones se extienden entre amigos",
 "Someone who adores you, or can't stand you, talks about you to their close friends, and slowly colors what they think of you (never worse than wary, by talk alone).": "Quien te adora, o no te soporta, habla de ti con sus amigos cercanos y, poco a poco, tiñe lo que piensan de ti (nunca peor que receloso, solo por hablar).",
 "Speakers' colors": "Colores de quien habla",
 "Color each speaker's dialogue": "Colorear los diálogos de cada personaje",
 "Quotes (\"…\") in a line, and the speaker's name, take that person's color. Leave it off if your preset or regex scripts already color quotes. The narrator keeps the quoted text color.": "Las frases entre comillas (\"…\") de un mensaje, y el nombre de quien habla, toman el color de esa persona. Déjalo apagado si tu preset o tus scripts de regex ya colorean las comillas. El narrador mantiene el color del texto entre comillas.",
 "Open a game to see its people's colors.": "Abre una partida para ver los colores de su gente.",
 "Pick colors again": "Elegir los colores de nuevo",
 "Your AI is choosing colors…": "Tu IA está eligiendo los colores…",
 "Your AI could not choose: automatic colors are used for now.": "Tu IA no pudo elegir: por ahora se usan colores automáticos.",
 "Colors set on a card (or yours) stay; your AI chooses the others, and Mundi keeps them readable and apart.": "Los colores puestos en una tarjeta (o el tuyo) se quedan; tu IA elige los demás, y Mundi los mantiene legibles y distintos entre sí.",
 "Your choice": "Tu elección",
