 "A color you choose is saved on their card.": "El color que elijas se guarda en su tarjeta."
,
 "Used to be: {0}, until day {1}": "Fueron: {0}, hasta el día {1}",
 "A couple": "Una pareja",
 "Forget": "Olvidar",
 "Family": "Familia",
 "No family yet.": "Todavía no hay familia.",
 "Feelings": "Sentimientos",
 "you": "ti",
 "Friends, couples and exes are feelings (below). Who lives together:": "Amigos, parejas y ex son sentimientos (abajo). Quién vive junto:",
 "Family in this household": "Familia en este hogar",
 "Add family": "Añadir familia",
 "Friends, a couple or roommates sharing this home: say how they get along under Relations.": "Amigos, una pareja o compañeros que comparten este hogar: di cómo se llevan en Relaciones.",
 "A household is people who live in the same home: a family, a couple, roommates. Put together the people who live together and say who is family. Everyone you leave out gets a home of their own, at random. You can skip this.": "Un hogar son personas que viven en la misma casa: una familia, una pareja, compañeros de piso. Junta a quienes viven juntos y di quién es familia. Quien quede fuera tendrá un hogar propio, al azar. Puedes saltarte esto.",
 "Everyone lives in the same house: say who is family and how they get along.": "Todos viven en la misma casa: di quién es familia y cómo se llevan.",
 "How you start with anyone in this world, not only who lives with you: family across town, a best friend, a rival, an old flame, someone you are dating.": "Cómo empiezas con cualquiera en este mundo, no solo con quien vive contigo: familia al otro lado de la ciudad, un mejor amigo, un rival, un viejo amor, alguien con quien sales.",
 "Between any two people of the house (or with you): family, friends, a couple, exes, people who can't stand each other…": "Entre dos personas cualesquiera de la casa (o contigo): familia, amigos, una pareja, ex, gente que no se soporta…",
 "Between any two people, in any household (or with you): family elsewhere, friends, a couple, exes, people who can't stand each other…": "Entre dos personas cualesquiera, de cualquier hogar (o contigo): familia en otro lugar, amigos, una pareja, ex, gente que no se soporta…",
 "\"As usual\": where they would start anyway.": "\"Como siempre\": donde empezarían de todos modos.",
 "As usual": "Como siempre",
 "feels about you": "siente por ti",
 "not family": "no es familia",
 "Used to be together": "Estuvieron juntos",
 "housemate (not family)": "compañero de casa (no es familia)",
 "The people who live with you: family, a partner, roommates. They share your home and your wallet, and you can play as any of them later (\"Play as\"). A partner or a friend: say how you get along under Your relations.": "Las personas que viven contigo: familia, una pareja, compañeros de piso. Comparten tu casa y tu cartera, y luego puedes jugar como cualquiera de ellas (\"Jugar como\"). Una pareja o un amigo: di cómo os lleváis en Tus relaciones.",
 "How they start with others": "Cómo empiezan con los demás",
 "From the start of every game: friendship and romance each way (\"As usual\": where they would start anyway), a couple, or exes.": "Desde el inicio de cada partida: amistad y romance de cada lado (\"Como siempre\": donde empezarían de todos modos), una pareja, o ex.",
 "From the start of every game: friendship each way (\"As usual\": where they would start anyway).": "Desde el inicio de cada partida: amistad de cada lado (\"Como siempre\": donde empezarían de todos modos).",
 "Who {0} is related to among the world's other people.": "Con quién está emparentado {0} entre las demás personas del mundo.",
 "Their friendship back": "Su amistad de vuelta",
 "Their romance back": "Su romance de vuelta",
 "Adult content": "Contenido adulto",
 "Adult content in this game": "Contenido adulto en esta partida",
 "On: the places, jobs, things to do, lore and people the world marks as adult are part of the game, and people's intimate profiles can be seen and changed. Off: all of it is left out (nothing is deleted: turning it on again brings it back). The world's adult-only people come only into a new game started with it on. Everyone in Mundi's worlds is an adult.": "Activado: los lugares, empleos, cosas por hacer, lore y personas que el mundo marca como adultos forman parte del juego, y los perfiles íntimos de las personas se pueden ver y cambiar. Desactivado: todo eso queda fuera (no se borra nada: al activarlo de nuevo, vuelve). Las personas solo para adultos del mundo solo llegan a una partida nueva empezada con esto activado. Todos en los mundos de Mundi son adultos.",
 "On: the places, jobs, things to do, lore and people a world marks as adult are part of the game, and people's intimate profiles can be seen and changed. Off (the default): all of it is left out. Change it any time in this game's settings (globe → Rules). Everyone in Mundi's worlds is an adult.": "Activado: los lugares, empleos, cosas por hacer, lore y personas que un mundo marca como adultos forman parte del juego, y los perfiles íntimos de las personas se pueden ver y cambiar. Desactivado (por defecto): todo eso queda fuera. Cámbialo cuando quieras en los ajustes de esta partida (globo → Reglas). Todos en los mundos de Mundi son adultos.",
 "The people of": "Las personas de",
 "The world's own characters, with their jobs, homes and the people they know. Keep the ones you want: someone you leave out isn't made, and the others' family, feelings and homes with them are left out too.": "Los personajes propios del mundo, con sus empleos, casas y las personas que conocen. Quédate con quien quieras: quien dejes fuera no se crea, y la familia, los sentimientos y las casas de los demás con esa persona quedan fuera también.",
 "The world's own characters, with their jobs, homes and the people they know. Keep the ones you want: someone you leave out isn't made, and the others' family, feelings and homes with them are left out too. {0} more person comes only with adult content.": "Los personajes propios del mundo, con sus empleos, casas y las personas que conocen. Quédate con quien quieras: quien dejes fuera no se crea, y la familia, los sentimientos y las casas de los demás con esa persona quedan fuera también. {0} persona más viene solo con contenido adulto.",
 "The world's own characters, with their jobs, homes and the people they know. Keep the ones you want: someone you leave out isn't made, and the others' family, feelings and homes with them are left out too. {0} more people come only with adult content.": "Los personajes propios del mundo, con sus empleos, casas y las personas que conocen. Quédate con quien quieras: quien dejes fuera no se crea, y la familia, los sentimientos y las casas de los demás con esa persona quedan fuera también. {0} personas más vienen solo con contenido adulto.",
 "Lives with {0}": "Vive con {0}",
 "Your start": "Tu comienzo",
 "the cards of the world's people you chose (made once, used again by later games)": "las tarjetas de las personas del mundo que elegiste (se crean una vez y se reutilizan en partidas futuras)",
 "yours": "tuyo",
 "Who you are when the story begins: where you live, what you have, who you already know.": "Quién eres cuando empieza la historia: dónde vives, qué tienes, a quién ya conoces.",
 "Write your own premise, or let your AI write it from lorebooks; then choose your home, your money and whom you know.": "Escribe tu propia premisa, o deja que tu IA la escriba a partir de lorebooks; luego elige tu casa, tu dinero y a quién conoces.",
 "Save as a start": "Guardar como comienzo",
 "Keep it for this world's next games (Library → Starts).": "Guárdalo para las próximas partidas de este mundo (Biblioteca → Comienzos).",
