 "Starts": "Comienzos",
 "No starts yet. Write a custom start in a new game and choose \"Save as a start\": it shows up here, for that world's next games.": "Ningún comienzo todavía. Escribe un comienzo personalizado en una partida nueva y elige \"Guardar como comienzo\": aparece aquí, para las próximas partidas de ese mundo.",
 "Choose a start to change it.": "Elige un comienzo para cambiarlo.",
 "World lore": "Lore del mundo",
