 "at most {0} rows": "como máximo {0} filas",
 "A busy place can match many lore rows: over the limit, the rows about the people here come first, then this place, then its area, then the season, weather and time.": "Un lugar concurrido puede coincidir con muchas filas de lore: por encima del límite, van primero las filas sobre las personas de aquí, luego este lugar, luego su zona, luego la estación, el clima y la hora.",
 "over the budget: only the hard limits are sent": "por encima del presupuesto: solo se envían los límites firmes",
