 "You bought the {0}.": "Compraste {0}.",
 "That isn't sold here.": "Eso no se vende aquí.",
 "Each job has its days and hours: your week is in the Calendar, and you get a reminder before each shift. Choose how hard you work; if you have plans, you can work part of the shift and then go. Some jobs pay extra at night or for overtime.": "Cada empleo tiene sus días y horarios: tu semana está en el Calendario, y recibes un recordatorio antes de cada turno. Elige cuánto te esfuerzas; si tienes planes, puedes trabajar parte del turno y luego irte. Algunos empleos pagan extra de noche o por horas extra.",
 "Performance and days off": "Desempeño y días libres",
 "Good shifts raise your performance; missing a shift, coming in late and slacking lower it. Book vacation days or call in sick ahead. How strict all this is depends on the work rules (This world → World).": "Los buenos turnos suben tu desempeño; faltar a un turno, llegar tarde y holgazanear lo bajan. Reserva días de vacaciones o avisa de que estás enfermo con antelación. Lo estricto que sea todo esto depende de las reglas de trabajo (Este mundo → Mundo).",
 "The next rank asks for shifts and time in your rank, a good performance and sometimes skills: the work screen and the Jobs app show what is missing. The top of a career takes about a game year.": "El siguiente rango pide turnos y tiempo en tu rango, un buen desempeño y a veces habilidades: la pantalla de trabajo y la app Empleos muestran lo que falta. La cima de una carrera tarda cerca de un año de juego.",
 "Career speed (×; 2: twice as fast)": "Velocidad de la carrera (×; 2: el doble de rápida)",
 "Work rules a new game starts with": "Reglas de trabajo con las que empieza una partida nueva",
