 "Well or badly": "Bien o mal",
 "Never badly": "Nunca mal",
 "How much pressure jobs put on you: days, absences, lateness, days off, how fast careers go. A preset sets them all; changing one rule makes it Custom.": "Cuánta presión ponen los empleos sobre ti: días, ausencias, retrasos, días libres, qué tan rápido avanzan las carreras. Un preajuste las define todas; cambiar una regla lo vuelve Personalizado.",
 "(default)": "(por defecto)",
 "Your own mix of the rules (Advanced).": "Tu propia mezcla de las reglas (Avanzado).",
 "After the last train": "Después del último tren",
 "Career speed": "Velocidad de la carrera",
 "(2×: careers twice as fast)": "(2×: carreras el doble de rápidas)",
 "Work hard": "Trabajar duro",
 "Your performance grows fastest, with a chance of a bonus. More tiring, a bit stressful.": "Tu desempeño crece más rápido, con posibilidad de bonificación. Más cansado y algo estresante.",
 "Chat with coworkers": "Charlar con los compañeros",
 "Better mood, closer to the colleagues on shift with you. Performance grows slowly.": "Mejor ánimo, más cerca de los compañeros de turno contigo. El desempeño crece despacio.",
 "Take it easy": "Tomarlo con calma",
 "Less tiring, but your performance drops and the boss notices.": "Menos cansado, pero tu desempeño baja y el jefe se da cuenta.",
 "Every job keeps its real days. A missed shift costs you, lateness counts after 15 minutes, and low performance can get you fired.": "Cada empleo mantiene sus días reales. Un turno perdido te cuesta, el retraso cuenta pasados 15 minutos, y el desempeño bajo puede costarte el empleo.",
 "About three quarters of the days, paid more per shift so a week earns the same. Gentler on absences and lateness; careers a little faster.": "Cerca de tres cuartas partes de los días, con más paga por turno para que la semana rinda lo mismo. Más indulgente con ausencias y retrasos; carreras un poco más rápidas.",
 "About half the days, paid more per shift so a week earns the same. Skip a shift whenever you like; nothing at work goes badly; careers faster.": "Cerca de la mitad de los días, con más paga por turno para que la semana rinda lo mismo. Sáltate un turno cuando quieras; nada sale mal en el trabajo; carreras más rápidas.",
 "They are not hiring.": "No están contratando.",
