 "Missed {0}: {1} free left": "Faltas: {0} · te quedan {1} sin penalización",
 "Missed {0} (and {1} more that won't fit in the {2} days left): {3} free left": "Faltas: {0} (y {1} más que no caben en los {2} días que quedan) · te quedan {3} sin penalización",
