 "{0}: {1}% back at the end, and you stay a season after.": "{0}: {1}% devuelto al final, y te quedas una estación después.",
 "Drop it? What you paid is gone. Enroll again within a year and half your classes count (once).": "¿Dejar el curso? Lo pagado no se devuelve. Inscríbete de nuevo antes de un año y la mitad de tus clases cuenta (una vez).",
 "Yes, drop it": "Sí, dejarlo",
 "Keep it": "Seguir",
 "Taking {0} of 2. One class a day for each, {1}.": "Cursando {0} de 2. Una clase al día en cada uno, {1}.",
 "Taking {0} of 2. Two at once is slower: each class counts less. One class a day for each, {1}.": "Cursando {0} de 2. Dos a la vez es más lento: cada clase cuenta menos. Una clase al día en cada uno, {1}.",
 "Pay, then go to class: a course lasts weeks and has a set number of classes (2 h each, {0}). Every class teaches you a little of its skills, and finishing gives you their levels for good. You can miss a few classes; miss too many and the course runs long, or you fail. Some jobs ask for a course first.": "Paga y ve a clase: un curso dura semanas y tiene un número fijo de clases (2 h cada una, {0}). Cada clase te enseña un poco de sus habilidades, y terminarlo te da sus niveles para siempre. Puedes faltar a algunas clases; si faltas demasiado, el curso se alarga o lo suspendes. Algunos empleos piden un curso antes.",
 "any five days a week": "cinco días cualquiera a la semana",
 "Paid when you enroll and at the start of each season; unpaid, the course waits.": "Se paga al inscribirte y al inicio de cada estación; sin pagar, el curso espera.",
 "Needs: {0}": "Necesita: {0}",
 "Needs: you have it ✓": "Necesita: ya lo tienes ✓",
 "{0} of {1} classes clash with your shifts (a missed class: no excuse for work).": "{0} de {1} clases coinciden con tus turnos (clase perdida: el trabajo no es excusa).",
 "With two courses at once, each class counts less: about {0} more.": "Con dos cursos a la vez, cada clase cuenta menos: aprox. {0} más.",
 "Taking it": "Cursándolo",
 "Asks for {0} first.": "Pide {0} primero.",
 "You can take two courses at most. Finish or drop one first.": "Puedes cursar dos cursos como máximo. Termina o deja uno primero.",
