 "{0}: {1} of the fee back when you finish.": "{0}: {1} de la cuota devuelto al terminar.",
 "{0}: {1} of the fee paid for you, if you stay a season at your job after finishing.": "{0}: {1} de la cuota pagado por ti, si te quedas una estación en tu empleo después de terminar.",
 "{0}: {1} of the fee back when you finish, if you stay a season at your job after finishing.": "{0}: {1} de la cuota devuelto al terminar, si te quedas una estación en tu empleo después.",
 "{0}: {1} of the fee paid for you, if you stay a season at it after finishing.": "{0}: {1} de la cuota pagado por ti, si te quedas una estación allí después de terminar.",
 "{0}: {1} of the fee back when you finish, if you stay a season at it after finishing.": "{0}: {1} de la cuota devuelto al terminar, si te quedas una estación allí después.",
 "Enrolled: {0}. {1} over about {2} {3}. One class a day at most, {4}.": "Inscrito: {0}. {1} en unos {2} {3}. Como mucho una clase al día, {4}.",
