 "Too late for a class today: a class takes two hours and must end before midnight.": "Demasiado tarde para una clase hoy: una clase dura dos horas y debe terminar antes de medianoche.",
 "There is no class today.": "Hoy no hay clase.",
 "Class is {0}.": "La clase es {0}.",
 "You are due at work then.": "A esa hora te toca trabajar.",
 "a make-up class, {0}": "una clase de recuperación, {0}",
 "a make-up class (charged by the class if it runs into a new season)": "una clase de recuperación (se cobra por clase si cae en una nueva estación)",
 "{0}: you are {1} {2} behind with {3} {4} left (one class a day): too many to make up. The course will fail when it ends.": "{0}: llevas {1} {2} de retraso, a falta de {3} {4} (una clase al día): demasiadas para recuperar. Suspenderás el curso cuando termine.",
 "{0}: you are {1} {2} behind with {3} {4} left (one class a day). One more day without a class and you fail the course.": "{0}: llevas {1} {2} de retraso, a falta de {3} {4} (una clase al día). Un día más sin clase y suspendes el curso.",
 "{0}: you are {1} {2} behind with {3} {4} left (one class a day): that uses all {5} free missed {6}. Each further one adds {7}.": "{0}: llevas {1} {2} de retraso, a falta de {3} {4} (una clase al día): eso usa las {5} faltas sin penalización. Cada falta más añade {7}.",
 "{0}: you are {1} {2} behind with {3} {4} left (one class a day): that uses all {5} free missed {6} and adds make-up classes. Each further one adds {7}.": "{0}: llevas {1} {2} de retraso, a falta de {3} {4} (una clase al día): eso usa las {5} faltas sin penalización y añade clases de recuperación. Cada falta más añade {7}.",
 "{0}: you are {1} {2} behind with {3} {4} left (one class a day): that uses {5} of {6} free missed classes.": "{0}: llevas {1} {2} de retraso, a falta de {3} {4} (una clase al día): eso usa {5} de {6} faltas sin penalización.",
 "{0}: one more missed class and you fail the course ({1} of {2} make-up classes used).": "{0}: una falta más y suspendes el curso ({1} de {2} clases de recuperación usadas).",
 "{0}: you have used all {1} free missed {2}. The next one adds {3}.": "{0}: has usado las {1} faltas sin penalización. La próxima añade {3}.",
 "{0}: you have missed {1} of {2} free classes.": "{0}: has faltado a {1} de {2} clases sin penalización.",
 "You failed {0}: too many missed classes. What you learned stays, but there is no certificate. If you enroll again within a year, half the classes you attended count (once).": "Suspendiste {0}: demasiadas faltas. Lo aprendido se queda, pero no hay certificado. Si te inscribes de nuevo antes de un año, cuenta la mitad de las clases a las que fuiste (una vez).",
 "{0}: class {1} of {2} done.": "{0}: clase {1} de {2} hecha.",
 "{0}: class {1} of {2} done. You can still miss {3} without a penalty.": "{0}: clase {1} de {2} hecha. Aún puedes faltar a {3} sin penalización.",
 "You finished {0}! Skills: {1}. {2} paid back {3}.": "¡Terminaste {0}! Habilidades: {1}. {2} te devolvió {3}.",
 "You finished {0}! Skills: {1}. You promised {2} to stay a season: leaving sooner pays back the rest of it.": "¡Terminaste {0}! Habilidades: {1}. Prometiste a {2} quedarte una estación: irte antes devuelve el resto.",
 "You paid {0} for {1}: classes go on.": "Pagaste {0} por {1}: las clases siguen.",
 "You paid {0}: classes go on.": "Pagaste {0}: las clases siguen.",
 "You have paid back your course sponsorship.": "Has terminado de devolver el patrocinio del curso.",
