 "When it pays": "Cuándo paga",
 "As usual (employer and merit: at enrollment; public: at the end)": "Como siempre (empleador y mérito: al inscribirse; pública: al final)",
 "Off the fee when you enroll": "Descontado de la cuota al inscribirte",
 "Back when you finish": "Devuelto al terminar",
 "Who qualifies (a condition)": "Quién tiene derecho (una condición)",
