 "Strengths: each option starts a skill": "Puntos fuertes: cada opción da una habilidad al empezar",
 "Off: the options are traits again, and their skills are forgotten.": "Desactivado: las opciones vuelven a ser rasgos, y sus habilidades se olvidan.",
 "A pick becomes skill levels instead of a trait (Good cook: Cooking 3).": "Una elección se convierte en niveles de habilidad en vez de un rasgo (Good cook: Cooking 3).",
 "former option": "opción antigua",
 "no longer offered: kept as a former option when saved": "ya no se ofrece: se guarda como opción antigua al guardar",
 "What traits do": "Lo que hacen los rasgos",
 "A line about each trait (shown when picking it and on the profile) and small effects from a fixed list, each within ±15% (a flat amount within ±1). An interest also says what it covers: doing something that fits it lifts the mood a little more. Standard traits (Calm, Shy, Music…) come with the game's own; change them here, or leave them to get the game's later tuning.": "Una línea sobre cada rasgo (se muestra al elegirlo y en el perfil) y pequeños efectos de una lista fija, cada uno dentro de ±15% (una cantidad fija dentro de ±1). Un interés también dice lo que abarca: hacer algo que encaje con él sube un poco más el ánimo. Los rasgos estándar (Calm, Shy, Music…) vienen con los del juego; cámbialos aquí, o déjalos para recibir los ajustes futuros del juego.",
