 "{0}: {1} over about {2} {3}, {4}. Fee {5}. {6}: {7} of the fee paid for you.": "{0}: {1} en unos {2} {3}, {4}. Cuota {5}. {6}: {7} de la cuota pagado por ti.",
 "{0}: {1} over about {2} {3}, {4}. Fee {5}. {6}: {7} of the fee back when you finish.": "{0}: {1} en unos {2} {3}, {4}. Cuota {5}. {6}: {7} de la cuota devuelto al terminar.",
 "{0}: {1} over about {2} {3}, {4}. Fee {5}. {6}: {7} of the fee paid for you, if you stay a season at your job after finishing.": "{0}: {1} en unos {2} {3}, {4}. Cuota {5}. {6}: {7} de la cuota pagado por ti, si te quedas una estación en tu empleo después de terminar.",
 "{0}: {1} over about {2} {3}, {4}. Fee {5}. {6}: {7} of the fee back when you finish, if you stay a season at your job after finishing.": "{0}: {1} en unos {2} {3}, {4}. Cuota {5}. {6}: {7} de la cuota devuelto al terminar, si te quedas una estación en tu empleo después.",
 "{0} of {1} classes clash with your shifts (a missed class: no excuse for work). That is more than it lets you miss: with these shifts you would fail it. Take days off, or pick a course at another time.": "{0} de {1} clases coinciden con tus turnos (clase perdida: el trabajo no es excusa). Es más de lo que el curso te deja faltar: con estos turnos lo suspenderías. Pide días libres, o elige un curso en otro horario.",
 "{0}, from your courses, is gone: courses teach skills now.": "{0}, de tus cursos, ya no está: los cursos ahora enseñan habilidades.",
 "{0}, from your courses, are gone: courses teach skills now.": "{0}, de tus cursos, ya no están: los cursos ahora enseñan habilidades.",
 "Your game now plays by the new traits and courses: strengths are skill levels, your personality and interests do small things, and courses take weeks. {0} A backup of the save was kept (Settings → Game → This save).": "Tu partida ahora sigue los nuevos rasgos y cursos: los puntos fuertes son niveles de habilidad, tu personalidad y tus intereses hacen pequeñas cosas, y los cursos duran semanas. {0} Se guardó una copia de la partida (Ajustes → Juego → Esta partida).",
 "Your game now plays by the new traits and courses: strengths are skill levels, your personality and interests do small things, and courses take weeks. A backup of the save was kept (Settings → Game → This save).": "Tu partida ahora sigue los nuevos rasgos y cursos: los puntos fuertes son niveles de habilidad, tu personalidad y tus intereses hacen pequeñas cosas, y los cursos duran semanas. Se guardó una copia de la partida (Ajustes → Juego → Esta partida).",
 "Who you are, and courses that take weeks": "Quién eres, y cursos que duran semanas",
 "Who you are matters: your strengths start your skills (Good cook · Cooking 3), and each personality trait and interest does something small. Habits have names of their own and make their skill train faster.": "Quién eres importa: tus puntos fuertes dan el comienzo de tus habilidades (Good cook · Cooking 3), y cada rasgo de personalidad e interés hace algo pequeño. Los hábitos tienen nombres propios y hacen que su habilidad se entrene más rápido.",
 "Courses take weeks: classes on a schedule, a few you can miss, make-up classes, two courses at once, fees by the season and help with the fee. Tokyo has 17.": "Los cursos duran semanas: clases con horario, algunas faltas permitidas, clases de recuperación, dos cursos a la vez, cuotas por estación y ayuda con la cuota. Tokio tiene 17.",
 "Start a job while you study for it, and your boss tells you when your next rank needs a course. No job is closed to your personality, and every roll gets the same bonus from your skill.": "Empieza en un empleo mientras estudias para él, y tu jefe te avisa cuando tu próximo rango pide un curso. Ningún empleo está cerrado a tu personalidad, y toda tirada recibe el mismo bono de tu habilidad.",
 "Gifts: buy them where they're sold. A romantic gift warms a crush, and an intimate one only lands with someone drawn to you.": "Regalos: cómpralos donde se venden. Un regalo romántico enciende un flechazo, y uno íntimo solo funciona con alguien que se siente atraído por ti.",
 "With adult content on, people undress for private moments and dress again after, and a world's people can bring outfits of their own. With it off, adult actions stay hidden everywhere.": "Con el contenido adulto activado, la gente se desviste en los momentos privados y se vuelve a vestir después, y la gente de un mundo puede traer su propia ropa. Desactivado, las acciones adultas quedan ocultas en todas partes.",
 "Tokyo's places and homes sit where they belong on each map, and characters get their new pictures when a world updates them.": "Los lugares y las casas de Tokio están donde deben en cada mapa, y los personajes reciben sus nuevas imágenes cuando un mundo las actualiza.",
 "Add to a built-in world with a file of your own: places, people, actions, lore and pictures, kept in SillyTavern's user files.": "Añade a un mundo incluido con un archivo tuyo: lugares, gente, acciones, lore e imágenes, guardados en los archivos de usuario de SillyTavern.",
 "Everything new in Portuguese and Spanish. Your games move to the new traits and courses once, with a backup kept in the save.": "Todo lo nuevo en portugués y español. Tus partidas pasan a los nuevos rasgos y cursos una vez, con una copia guardada en la partida.",
 "Rewards": "Recompensas",
 "Pick a life goal": "Elige una meta de vida",
 "It guides your days, and finishing it gives you a perk.": "Guía tus días, y al completarla recibes una ventaja.",
 "One goal at a time; switch whenever you like, nothing is lost.": "Una meta a la vez; cambia cuando quieras, no se pierde nada.",
 "Pick a life goal in the Goals app: it guides your days, and finishing it gives you a perk.": "Elige una meta de vida en la app Metas: guía tus días, y al completarla recibes una ventaja.",
 "Pick your next life goal in the Goals app.": "Elige tu próxima meta de vida en la app Metas.",
