 "That rumor stops here.": "Ese rumor termina aquí.",
 "No longer: {0}.": "Ya no: {0}.",
 "{0}: finishing this goal pays double.": "{0}: completar esta meta paga el doble.",
 "No {0} to pay this week.": "Sin {0} que pagar esta semana.",
 "At {0}, it's as if it never happened: a clean slate.": "En {0}, es como si nunca hubiera pasado: borrón y cuenta nueva.",
 "You learned that {0} is in love with you.": "Has descubierto que {0} está enamorado de ti.",
 "You learned that {0} has a crush on you.": "Has descubierto que {0} tiene un flechazo contigo.",
 "You learned that {0} is in love with {1}.": "Has descubierto que {0} está enamorado de {1}.",
 "You learned that {0} has a crush on {1}.": "Has descubierto que {0} tiene un flechazo con {1}.",
 "You learned that {0} is still hurt: {1}.": "Has descubierto que {0} sigue dolido: {1}.",
 "You learned what {0} wants: {1}.": "Has descubierto lo que quiere {0}: {1}.",
 "You learned that {0} could never be attracted to you.": "Has descubierto que {0} jamás se sentiría atraído por ti.",
 "You learned that {0} is only sometimes drawn to people like you.": "Has descubierto que {0} solo a veces se siente atraído por gente como tú.",
 "You learned that {0} could be attracted to you.": "Has descubierto que {0} podría sentirse atraído por ti.",
 "You found out {0}'s secret: {1}.": "Has descubierto el secreto de {0}: {1}.",
 "You found out that {0} and {1} are secretly together.": "Has descubierto que {0} y {1} están juntos en secreto.",
 "Life goals and life points": "Metas de vida y puntos de logro",
 "Like in The Sims: follow one life goal at a time, in the Goals app. Nothing is required; a goal gives your days a direction, and finishing it gives you something for good.": "Como en Los Sims: sigue una meta de vida a la vez, en la app Metas. Nada es obligatorio; una meta da un rumbo a tus días, y al completarla recibes algo para siempre.",
 "Like in The Sims: follow one life goal at a time, on the Goals page of your journal. Nothing is required; a goal gives your days a direction, and finishing it gives you something for good.": "Como en Los Sims: sigue una meta de vida a la vez, en la página Metas de tu diario. Nada es obligatorio; una meta da un rumbo a tus días, y al completarla recibes algo para siempre.",
 "A life goal": "Una meta de vida",
 "A few steps toward something you want (cooking for friends, the top of a career, every corner of the city). The goals suggested first suit how you started. The AI knows the goal you follow.": "Unos pasos hacia algo que quieres (cocinar para tus amigos, la cima de una carrera, cada rincón de la ciudad). Las metas sugeridas primero encajan con cómo empezaste. La IA conoce la meta que sigues.",
 "Steps": "Pasos",
 "Each step lists what it asks for and how far you are (\"Meals cooked 6/15\"). Steps are done in order, as soon as everything they ask for holds; some must keep holding for a few days. What you do counts for the goal you follow, from when you picked it.": "Cada paso indica lo que pide y cuánto llevas (\"Comidas cocinadas 6/15\"). Los pasos se hacen en orden, en cuanto se cumple todo lo que piden; algunos deben seguir cumpliéndose unos días. Lo que haces cuenta para la meta que sigues, desde que la elegiste.",
 "Switch whenever you like: the goal you leave is paused and keeps its finished steps and what it counted, for when you pick it again.": "Cambia cuando quieras: la meta que dejas queda en pausa y conserva sus pasos completados y lo que contó, para cuando la elijas de nuevo.",
 "A perk": "Una ventaja",
 "Finishing a goal gives a perk: a small change to the game's numbers that lasts for good (lower prices, energy that lasts longer, a bonus on rolls). A goal gives a perk, not a trait: traits are who you are. Your perks are in the Goals app and on your profile; when two touch the same thing, percentages multiply and flat bonuses add.": "Completar una meta da una ventaja: un pequeño cambio en los números del juego que dura para siempre (precios más bajos, energía que dura más, un bono en las tiradas). Una meta da una ventaja, no un rasgo: los rasgos son quién eres. Tus ventajas están en la app Metas y en tu perfil; cuando dos tocan lo mismo, los porcentajes se multiplican y los bonos fijos se suman.",
 "Each step of your goal gives life points (100), and finishing it more (200). Festivals and city events (the first time each year), street stories, secrets and storylines you followed give a few too, up to 60 a day.": "Cada paso de tu meta da puntos de logro (100), y completarla da más (200). Los festivales y eventos de la ciudad (la primera vez cada año), las historias callejeras, los secretos y las tramas que seguiste dan algunos también, hasta 60 al día.",
 "Spend life points in the Goals app's Rewards tab: a lucky day, energy full now, a nudge in how someone feels about you, a fresh start with someone, a trait swapped… Each shows its price and how often it can be used; some only work in certain places, and a world may have its own.": "Gasta puntos de logro en la pestaña Recompensas de la app Metas: un día de suerte, energía al máximo ahora, un empujoncito en lo que alguien siente por ti, un nuevo comienzo con alguien, un rasgo cambiado… Cada una muestra su precio y cada cuánto se puede usar; algunas solo funcionan en ciertos lugares, y un mundo puede tener las suyas.",
 "Your life goal, its steps and the goals you could follow; its Rewards tab spends your life points.": "Tu meta de vida, sus pasos y las metas que podrías seguir; su pestaña Recompensas gasta tus puntos de logro.",
