 "1 point": "1 punto",
 "Goals & rewards": "Metas y recompensas",
 "A Home hides Realm, Economy, RPG and Goals & rewards (a Home is always Life-Sim, with life goals off). Jobs and courses happen off-screen.": "Un Home oculta Reino, Economía, RPG y Metas y recompensas (un Home siempre es Life-Sim, con las metas de vida desactivadas). Los empleos y cursos ocurren fuera de escena.",
 "Life goals are off in this world (Features → Systems): nothing here is offered in a game until they are on.": "Las metas de vida están desactivadas en este mundo (Funciones → Sistemas): nada de aquí se ofrece en una partida hasta que se activen.",
 "General goals": "Metas generales",
 "The game's own goals, offered in every world whose systems they need. Untick one this world can't do; give it a name of your own (empty: the game's name). A renamed goal keeps the game's steps and perk, so later changes to them still reach this world.": "Las metas del propio juego, ofrecidas en todo mundo que tenga los sistemas que necesitan. Desmarca una que este mundo no pueda cumplir; dale un nombre tuyo (vacío: el nombre del juego). Una meta renombrada conserva los pasos y la ventaja del juego, así que los cambios futuros en ellos siguen llegando a este mundo.",
 "{0} Not offered here: needs {1} on.": "{0} No se ofrece aquí: necesita {1} activado.",
 "{0} This world's own goal with the same id takes its place.": "{0} Una meta propia de este mundo con el mismo id ocupa su lugar.",
 "This world's own goals": "Metas propias de este mundo",
 "Goals of this world, shown with the general ones in their categories. A step that names one of the world's people or a storyline needs another way that names nobody: a game can leave them out. A goal removed after games picked it is gone from them, perk included.": "Metas de este mundo, mostradas junto con las generales en sus categorías. Un paso que nombra a una persona del mundo o una trama necesita otra vía que no nombre a nadie: una partida puede dejarlas fuera. Una meta eliminada después de que las partidas la eligieran desaparece de ellas, ventaja incluida.",
 "No goals of its own yet.": "Ninguna meta propia todavía.",
 "can't work yet": "aún no puede funcionar",
 "may not be offered": "puede que no se ofrezca",
 "General rewards": "Recompensas generales",
 "What life points buy in every world. Untick one, rename it, or give it a price of its own (empty: the game's).": "Lo que compran los puntos de logro en todo mundo. Desmarca una, renómbrala o dale un precio propio (vacío: el del juego).",
 "{0} Not sold here: needs {1} on.": "{0} No se vende aquí: necesita {1} activado.",
 "{0} This world's own item with the same id takes its place.": "{0} Un artículo propio de este mundo con el mismo id ocupa su lugar.",
 "This world's own rewards": "Recompensas propias de este mundo",
 "A boost for a few days, a need full now, or one of the game's one-off kinds under a name of this world's (as Tokyo's omikuji is a lucky week).": "Un impulso durante unos días, una necesidad al máximo ahora, o uno de los tipos únicos del juego bajo un nombre de este mundo (como el omikuji de Tokio, que es una semana de suerte).",
 "No rewards of its own yet.": "Ninguna recompensa propia todavía.",
 "World saved. Not working yet (Goals & rewards): {0}.": "Mundo guardado. Aún no funciona (Metas y recompensas): {0}.",
 "⭐ New goal": "⭐ Nueva meta",
 "New goal": "Nueva meta",
 "New perk": "Nueva ventaja",
 "New reward": "Nueva recompensa",
 "Can't work yet": "Aún no puede funcionar",
 "May not be offered": "Puede que no se ofrezca",
 "Category": "Categoría",
 "A category of its own…": "Una categoría propia…",
 "Its own category (a group of its own in the Goals app)": "Su propia categoría (un grupo propio en la app Metas)",
 "Night life": "Vida nocturna",
 "Starts it suits (suggested first to players who start so)": "Inicios que le encajan (se sugiere primero a quien empieza así)",
 "It can't do without: {0}": "No funciona sin: {0}",
 "It can't do without: nothing in particular": "No funciona sin: nada en particular",
 "A game with one of these off doesn't offer it.": "Una partida con uno de estos desactivado no la ofrece.",
 "A game with one of these off doesn't sell it.": "Una partida con uno de estos desactivado no la vende.",
 "Adult (only with adult content on)": "Adulto (solo con contenido adulto activado)",
 "Done in order, each when all its objectives hold (or one of its other ways does). Three or four are best; one to six work. Counted objectives (did, attended) count only while the goal is the one followed; the rest count at once.": "Se hacen en orden, cada uno cuando se cumplen todos sus objetivos (o una de sus otras vías). Tres o cuatro es lo mejor; de uno a seis funcionan. Los objetivos contados (did, attended) solo cuentan mientras la meta es la que se sigue; los demás cuentan al instante.",
 "Step {0}": "Paso {0}",
 "Move up": "Subir",
 "Move down": "Bajar",
 "Remove this step": "Quitar este paso",
 "What it says (in the Goals app)": "Lo que dice (en la app Metas)",
 "Objectives (all of them, separated by ;)": "Objetivos (todos ellos, separados por ;)",
 "Or instead (way {0})": "O en su lugar (vía {0})",
 "Remove this way": "Quitar esta vía",
 "Add another way to do it": "Añadir otra forma de hacerlo",
 "The objectives must keep holding": "Los objetivos deben seguir cumpliéndose",
