 "Tracks by gender": "Modalidades por género",
 "One job and one listing, with its own ranks, pay, hours and gates for a gender (the AV actor's track beside the actresses'). What a track leaves empty is the job's own; its work events come on top of the job's. A player whose gender has no track picks one of the open tracks once, when hired. Write a track for every gender that has one, even when it is the job as written.": "Un solo empleo y una sola oferta, con rangos, sueldo, horarios y requisitos propios para un género (la modalidad del actor de AV junto a la de las actrices). Lo que una modalidad deja vacío es lo del propio empleo; sus eventos de trabajo vienen además de los del empleo. Un jugador cuyo género no tiene modalidad elige una de las abiertas, una vez, al ser contratado. Escribe una modalidad para cada género que tenga una, incluso cuando sea el empleo tal como está escrito.",
