 "You know {0}'s drive now: {1}.": "Ahora conoces la libido de {0}: {1}.",
 "No": "No",
 "General": "General",
 "Neutral": "Neutral",
 "Color": "Color",
 "They won't serve you here this week. {0} more days.": "Aquí no te atenderán esta semana. {0} días más.",
 "They won't serve you here this week. 1 more day.": "Aquí no te atenderán esta semana. 1 día más.",
 "Bills are weekly. One left unpaid for a week is cut off until you pay what is overdue (for the rent, you are locked out of your home). You can pay part of a bill at any time.": "Las facturas son semanales. Una sin pagar durante una semana se corta hasta que pagues lo atrasado (con el alquiler, te quedas fuera de casa). Puedes pagar parte de una factura en cualquier momento.",
 "Bills are weekly. One left unpaid for a week stops until you pay what is overdue (for the rent, the landlord locks you out). You can pay part of a bill at any time.": "Las facturas son semanales. Una sin pagar durante una semana se detiene hasta que pagues lo atrasado (con el alquiler, el casero te deja fuera). Puedes pagar parte de una factura en cualquier momento.",
 "You are locked out: pay {1} of rent {0} to get back in.": "No puedes entrar: paga {1} de alquiler {0} para volver a entrar.",
 "The landlord locked you out: pay {1} of rent {0} to get back in.": "El casero te dejó fuera: paga {1} de alquiler {0} para volver a entrar.",
 "Pay {1} {0} to get back in": "Paga {1} {0} para volver a entrar",
 "Last day for the rent: pay {1} {2} today, or you will be locked out tomorrow.": "Último día para el alquiler: paga {1} {2} hoy, o mañana te quedas fuera.",
 "Last day for the rent: pay {1} {2} today, or the landlord locks you out tomorrow.": "Último día para el alquiler: paga {1} {2} hoy, o mañana el casero te deja fuera.",
 "Last day for {0}: pay {1} {2} today, or it is cut off tomorrow.": "Último día para {0}: paga {1} {2} hoy, o mañana se corta.",
 "Last day for {0}: pay {1} {2} today, or it stops tomorrow.": "Último día para {0}: paga {1} {2} hoy, o mañana se detiene.",
 "{0} are weekly bills: pay them {1} (they turn red when due). One left unpaid for a week stops (or, for the rent, you are locked out of your home) until you pay what is overdue; you can pay part of a bill, and one that stopped owes no more weeks.": "{0} son facturas semanales: págalas {1} (se ponen en rojo al vencer). Una sin pagar durante una semana se detiene (o, con el alquiler, te quedas fuera de casa) hasta que pagues lo atrasado; puedes pagar parte de una factura, y una detenida no suma más semanas.",
 "Locked out tomorrow": "Fuera de casa mañana",
 "Cut off tomorrow": "Se corta mañana",
 "Locked out in {0} days": "Fuera de casa en {0} días",
 "Cut off in {0} days": "Se corta en {0} días",
 "{0} gets you back in": "Con {0} vuelves a entrar",
 "{0} gets it back": "Con {0} vuelve",
 "Pay {0} toward it": "Pagar {0} a cuenta",
 "{0} paid so far": "{0} pagados hasta ahora",
 "Not enough money ({0}).": "No tienes suficiente dinero ({0}).",
 "Paid {0}: {1} still to pay.": "Pagado {0}: faltan {1}.",
 "Or move somewhere cheaper: {0}, {1} a week, paid one week in advance.": "O múdate a un sitio más barato: {0}, {1} a la semana, con una semana por adelantado.",
 "Your rent at home is now {0} a week ({1}).": "Tu alquiler en casa ahora es {0} a la semana ({1}).",
 "Rent you pay there, a week (empty: the home's own, {0}; until you move)": "Alquiler que pagas allí, a la semana (vacío: el de la propia casa, {0}; hasta que te mudes)",
 "Life goals, and Tokyo after dark": "Metas de vida, y Tokio al caer la noche",
 "Life goals: follow one through its steps, switch any time without losing what it counted, and finishing it gives a perk for good. Tokyo has 25 of its own.": "Metas de vida: sigue una por sus pasos, cambia cuando quieras sin perder lo que contó, y terminarla te da una ventaja para siempre. Tokio tiene 25 propias.",
 "Life points from steps and small moments buy a lucky day, a nudge, an invitation, insight into someone and Tokyo's shrine charms.": "Los puntos de vida de los pasos y de pequeños momentos compran un día de suerte, un empujoncito, una invitación, una mirada a alguien y los amuletos de los santuarios de Tokio.",
 "With adult content on, Tokyo's love life plays: private moments go great, good or awkward, and you learn what someone likes and won't do.": "Con el contenido adulto activado, la vida amorosa de Tokio se juega: los momentos privados salen geniales, bien o incómodos, y descubres lo que a alguien le gusta y lo que no hace.",
 "Desire, and a drive for you and everyone: some want you often, some rarely, and someone who wants you may make the move.": "Deseo, y una libido para ti y para todos: algunos te quieren a menudo, otros rara vez, y quien te desea puede dar el primer paso.",
 "Risky places can get you caught: a fee, a week's ban, a rumor and a partner who hears about it.": "Los lugares arriesgados pueden hacer que te pillen: una multa, una semana vetado, un rumor y una pareja que se entera.",
 "Careers with a track for each gender: the video industry and the new esthe therapist at Aroma Room Lily, with pole and massage classes.": "Carreras con un camino para cada género: la industria del vídeo y la nueva terapeuta de estética en Aroma Room Lily, con clases de pole dance y de masaje.",
 "Rent can be paid in part, you're warned the day before the lock, and the Homes app shows the way back in.": "El alquiler se puede pagar en parte, te avisan el día antes del bloqueo, y la app Casas muestra cómo volver a entrar.",
 "Everything new in Portuguese and Spanish, and fixes for every world: a need that empties no longer hits all at once.": "Todo lo nuevo en portugués y español, y arreglos para todos los mundos: una necesidad que se vacía ya no golpea de una vez.",
 "A capsule, a ryokan, a manga café.": "Una cápsula, un ryokan, un manga café.",
