 "Other languages people may share with you": "Otros idiomas que la gente puede compartir contigo",
 "Otherwise their card isn't made, and ties and households with them are left out.": "Si no, su tarjeta no se crea, y los lazos y hogares con él quedan fuera.",
 "Outcomes several things to do draw from (one omikuji for every shrine), each told in that action's own words (Things to do › A shared table).": "Resultados que sacan varias cosas que hacer (un omikuji para cada santuario), cada uno contado con las palabras de esa acción (Cosas que hacer › Una tabla compartida).",
