 "Short description (on its card)": "Descripción corta (en su tarjeta)",
 "Short one-off stories that happen at a place: a setup told to the AI (unnamed people, or one of the world's people by name) and two or three choices.": "Historias cortas, de una vez, que pasan en un lugar: una situación contada a la IA (gente sin nombre, o alguien del mundo por su nombre) y dos o tres opciones.",
