 "The AI may describe unnamed staff, regulars and passers-by at every place, not only where a place says who is around.": "La IA puede describir personal, habituales y transeúntes sin nombre en cualquier lugar, no solo donde el lugar dice quién anda por ahí.",
 "The card chosen when a new game opens.": "La tarjeta elegida cuando se abre una partida nueva.",
 "The cards a new game offers: where you live, what you have, who you already know, and what the AI is told. The player can still write a custom one.": "Las tarjetas que ofrece una partida nueva: dónde vives, qué tienes, a quién conoces ya y qué se le dice a la IA. El jugador aún puede escribir uno propio.",
 "The custom in a sentence (for the AI)": "La costumbre en una frase (para la IA)",
 "The first": "El primero",
 "The language everyone here speaks, for a newcomer who doesn't: the player's level in it shapes what the AI is told, and time with people who speak only it trains it.": "El idioma que todos hablan aquí, para un recién llegado que no lo habla: el nivel del jugador en él da forma a lo que se le dice a la IA, y el tiempo con quien solo lo habla lo entrena.",
 "The most fitting picture is shown: rain in summer at night first, then rain at night, summer at night, night.": "Se muestra la imagen que mejor encaja: lluvia en verano de noche primero, luego lluvia de noche, verano de noche, noche.",
 "The rank they hold": "El puesto que ocupa",
 "The return gift": "El regalo de vuelta",
 "The same conditions as goals and things to do. One that can't be read never holds.": "Las mismas condiciones que las metas y las cosas que hacer. Una que no se puede leer nunca se cumple.",
