 "They win over free time, not over a work shift. Hours past 24 run into the night (21–26 is 21:00 to 2:00).": "Ganan al tiempo libre, no a un turno de trabajo. Las horas pasadas las 24 siguen en la noche (21–26 es de 21:00 a 2:00).",
 "Things to do play out in the scene": "Las cosas que hacer se juegan en la escena",
 "Things you keep from things to do and street stories; most can be given. Some are sold at places, for gifts.": "Cosas que guardas de cosas que hacer e historias callejeras; la mayoría se pueden regalar. Algunas se venden en lugares, para regalos.",
