 "You and {0} have taught each other all you can for now.": "Tú y {0} os habéis enseñado todo lo que podíais por ahora.",
 "Your {0} with {1} lapsed: no session in {2} days.": "Tu {0} con {1} caducó: ninguna sesión en {2} días.",
 "{0} called off your {1}.": "{0} canceló vuestro {1}.",
 "{0} said no to training together. It won't come up with them again for a while.": "{0} dijo que no a entrenar juntos. No volverá a surgir con esa persona en un tiempo.",
 "Offers {0}: {1}. About twice a week, an hour each time.": "Ofrece {0}: {1}. Unas dos veces por semana, una hora cada vez.",
 "{0} teaches you {1} and you teach {2} {3}": "{0} te enseña {1} y tú le enseñas {3} a {2}",
 "{0} teaches you {1}": "{0} te enseña {1}",
