 "You learn {0}: level {1} → {2}": "Aprendes {0}: nivel {1} → {2}",
 "You learn {0}: level {1} (done)": "Aprendes {0}: nivel {1} (terminado)",
 "{0} learns {1}: level {2} → {3}": "{0} aprende {1}: nivel {2} → {3}",
 "{0} learns {1}: level {2} (done)": "{0} aprende {1}: nivel {2} (terminado)",
 "{0}/{1} this week": "{0}/{1} esta semana",
 "last today": "la última hoy",
 "last yesterday": "la última ayer",
 "last {0} days ago": "la última hace {0} días",
 "no session yet": "ninguna sesión todavía",
 "lapses tomorrow": "caduca mañana",
 "lapses in {0} days": "caduca en {0} días",
 "End": "Terminar",
 "Talk about it: a friend who's good at something you're not (level {0} or more, {1} above you) may teach you, or trade lessons, and you can teach what you know. Up to {2} at a time, {3} sessions a week, an hour each with them beside you; unused for {4} days, it lapses.": "Habladlo: un amigo que es bueno en algo en lo que tú no (nivel {0} o más, {1} por encima de ti) puede enseñarte, o intercambiar clases, y tú puedes enseñar lo que sabes. Hasta {2} a la vez, {3} sesiones a la semana, una hora cada una con esa persona a tu lado; sin usar durante {4} días, caduca.",
 "Finished: {0}": "Terminados: {0}",
 "Lessons with {0}, {1} a week (Training together).": "Clases con {0}, {1} a la semana (Entrenar juntos).",
 "Language exchange with {0}": "Intercambio de idiomas con {0}",
 "Trade lessons with {0}": "Intercambiar clases con {0}",
 "Lesson with {0}": "Clase con {0}",
 "Teach {0}": "Enseñar a {0}",
 "{0} · 1 hour": "{0} · 1 hora",
 "What they're good at, for training together (teaching takes 6; empty: what their job asks)": "En qué es buena, para entrenar juntos (enseñar pide 6; vacío: lo que pide su trabajo)",
 "Start teaching someone": "Empezar a enseñar a alguien",
 "A session where you teach": "Una sesión en la que enseñas",
 "Someone you teach learns all you can teach": "Alguien a quien enseñas aprende todo lo que puedes enseñar",
 "Someone teaches you all they can": "Alguien te enseña todo lo que puede",
 "Teach 10 sessions": "Dar 10 sesiones",
 "Two who learn all you can teach": "Dos que aprenden todo lo que puedes enseñar",
 "Those you teach learn 50% more each session.": "Quienes enseñas aprenden un 50% más en cada sesión.",
 "Start teaching someone · Teach 10 sessions · Someone you teach learns all you can teach · Two who learn all you can teach": "Empezar a enseñar a alguien · Dar 10 sesiones · Alguien a quien enseñas aprende todo lo que puedes enseñar · Dos que aprenden todo lo que puedes enseñar",
 "Training together, and a city easier to find your way in": "Entrenar juntos, y una ciudad donde es más fácil orientarse",
 "Training together: a friend who's good at what you're not can teach you, you can teach what you know, or you trade (a language exchange). Agree on it in conversation; it replaces apprentices.": "Entrenar juntos: un amigo que es bueno en lo que tú no puede enseñarte, tú puedes enseñar lo que sabes, o intercambiáis (un intercambio de idiomas). Se acuerda en la conversación; sustituye a los aprendices.",
 "Suggest it in your own words and they answer yes or no; someone may offer it when the talk turns that way, and you accept or turn it down on a card.": "Propónlo con tus propias palabras y te responden sí o no; alguien puede ofrecerlo cuando la conversación vaya por ahí, y lo aceptas o lo rechazas en una tarjeta.",
 "Tokyo's Streamer: anyone can stream for little at first, then choose games and chatting or, with adult content on, adult streams.": "Streamer en Tokio: cualquiera puede hacer directos por poco al principio, y luego elegir juegos y charla o, con contenido adulto activado, directos para adultos.",
 "Tokyo's maps change at night: every district and the whole city light up from 18:00 (neon, lanterns, Tokyo Tower), with the pins where they were.": "Los mapas de Tokio cambian de noche: cada distrito y la ciudad entera se iluminan desde las 18:00 (neón, farolillos, la Torre de Tokio), con los marcadores donde estaban.",
 "Tokyo sounds like Tokyo: every place plays real recordings (its crowds, an izakaya, the Shibuya crossing, cicadas in summer, a temple bell), quieter when the place is quiet, and silent while it's closed.": "Tokio suena a Tokio: cada lugar reproduce grabaciones reales (la multitud, un izakaya, el cruce de Shibuya, las cigarras en verano, la campana de un templo), más bajas cuando el lugar está vacío y en silencio mientras está cerrado.",
 "The map has a Find button: type part of a name to see every matching place, its district and the trip there.": "El mapa tiene un botón Buscar: escribe parte de un nombre para ver todos los lugares que coinciden, su distrito y el trayecto hasta allí.",
 "Things to do show the skill they train, and each skill on the Profile lists where to practise it, when, and what it waits for.": "Las cosas que hacer muestran la habilidad que entrenan, y cada habilidad en el Perfil indica dónde practicarla, cuándo y qué espera.",
 "Notices stay as long as they need and count down one at a time, with a Log of them all in the ☰ menu; cards that come to you show one at a time.": "Los avisos se quedan lo que necesitan y cuentan de uno en uno, con un Registro de todos en el menú ☰; las tarjetas que te llegan aparecen de una en una.",
 "The main menu tells you when Mundi has an update and offers to update and reload. The Jobs app sorts its openings.": "El menú principal te avisa cuando Mundi tiene una actualización y ofrece actualizar y recargar. La app Empleos ordena sus ofertas.",
 "Everything new in Portuguese and Spanish, and fixes to the map's card, a character's menu, the scene's text box and Say.": "Todo lo nuevo en portugués y español, y arreglos en la tarjeta del mapa, el menú de un personaje, el cuadro de texto de la escena y Decir.",
 "The world": "El mundo",
 "The Home": "El Home",
